export function computeInvoice(input = {}) {
  const lines = input == null ? undefined : input.lines;

  if (!Array.isArray(lines)) {
    throw new RangeError("lines must be an array");
  }

  const requestedDiscountKobo =
    input.discountKobo === undefined ? 0 : input.discountKobo;

  if (
    !Number.isInteger(requestedDiscountKobo) ||
    requestedDiscountKobo < 0
  ) {
    throw new RangeError("discountKobo must be a non-negative integer");
  }

  const normalizedLines = new Array(lines.length);
  let invoiceSubtotalKobo = 0n;

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    const unitPriceKobo = line?.unitPriceKobo;
    const qty = line?.qty;

    if (!Number.isInteger(unitPriceKobo) || unitPriceKobo < 0) {
      throw new RangeError("unitPriceKobo must be a non-negative integer");
    }

    if (!Number.isInteger(qty) || qty < 1) {
      throw new RangeError("qty must be a positive integer");
    }

    const lineSubtotalKobo = BigInt(unitPriceKobo) * BigInt(qty);

    normalizedLines[index] = {
      sku: line?.sku,
      vatExempt: line?.vatExempt,
      subtotalKobo: lineSubtotalKobo,
    };

    invoiceSubtotalKobo += lineSubtotalKobo;
  }

  const requestedDiscountBigInt = BigInt(requestedDiscountKobo);
  const appliedDiscountKobo =
    requestedDiscountBigInt < invoiceSubtotalKobo
      ? requestedDiscountBigInt
      : invoiceSubtotalKobo;

  const discountAllocations = new Array(lines.length).fill(0n);

  if (invoiceSubtotalKobo > 0n && appliedDiscountKobo > 0n) {
    const remainders = new Array(lines.length);
    let allocatedDiscountKobo = 0n;

    for (let index = 0; index < normalizedLines.length; index += 1) {
      const numerator =
        appliedDiscountKobo * normalizedLines[index].subtotalKobo;
      const allocation = numerator / invoiceSubtotalKobo;
      const remainder = numerator % invoiceSubtotalKobo;

      discountAllocations[index] = allocation;
      allocatedDiscountKobo += allocation;
      remainders[index] = { index, remainder };
    }

    let leftoverKobo = appliedDiscountKobo - allocatedDiscountKobo;

    if (leftoverKobo > 0n) {
      remainders.sort((a, b) => {
        if (a.remainder > b.remainder) return -1;
        if (a.remainder < b.remainder) return 1;
        return a.index - b.index;
      });

      for (let rank = 0; leftoverKobo > 0n; rank += 1) {
        discountAllocations[remainders[rank].index] += 1n;
        leftoverKobo -= 1n;
      }
    }
  }

  let invoiceVatKobo = 0n;

  const resultLines = normalizedLines.map((line, index) => {
    const lineDiscountKobo = discountAllocations[index];
    const netKobo = line.subtotalKobo - lineDiscountKobo;
    const lineVatKobo =
      line.vatExempt === false ? (netKobo * 3n + 20n) / 40n : 0n;

    invoiceVatKobo += lineVatKobo;

    return {
      sku: line.sku,
      subtotalKobo: Number(line.subtotalKobo),
      discountKobo: Number(lineDiscountKobo),
      netKobo: Number(netKobo),
      vatKobo: Number(lineVatKobo),
    };
  });

  const totalKobo =
    invoiceSubtotalKobo - appliedDiscountKobo + invoiceVatKobo;

  return {
    subtotalKobo: Number(invoiceSubtotalKobo),
    discountKobo: Number(appliedDiscountKobo),
    vatKobo: Number(invoiceVatKobo),
    totalKobo: Number(totalKobo),
    lines: resultLines,
  };
}
